    correction: [{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 14 و 12 و 18 كلّها مضاعفات لـ 2"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">14a + 12b + 18 = 2(7a + 6b + 9)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">7a + 6b = 272</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">272 + 9 = 281</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">2 × 281 = 562</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 562</span>"}],
