    correction: [{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">3(8a + 10b) - 6(a + 3b) = 24a + 30b - 6a - 18b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">24a + 30b - 6a - 18b = 24a - 6a + 30b - 18b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">24a + 30b - 6a - 18b = 18a + 12b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">18a + 12b = 2(9a + 6b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">2(9a + 6b) = 2 × 108</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 216</span>"}],
