    correction: [{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">3(4a + 12b) - 4(a + 5b) = 12a + 36b - 4a - 20b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">12a + 36b - 4a - 20b = 12a - 4a + 36b - 20b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">12a + 36b - 4a - 20b = 8a + 16b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">8a + 16b = 2(4a + 8b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">2(4a + 8b) = 2 × 80</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 160</span>"}],
